1.query:
timeseries reqs = sum(dt.service.request.count), filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd requests = arraySum(reqs)
| fields requests, reqs, interval, timeframe

2.query:
timeseries { reqs = sum(dt.service.request.count), fails = sum(dt.service.request.failure_count) }, filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd failure_rate_pct = (arraySum(fails) * 100.0) / arraySum(reqs)
| fields failure_rate_pct, fails, interval, timeframe

3.query:
timeseries c4xx = sum(dt.service.request.count), filter: { k8s.namespace.name == "dydemo" and http.response.status_code >= 400 and http.response.status_code < 500 }
| fieldsAdd client_errors = arraySum(c4xx)
| fields client_errors, c4xx, interval, timeframe

4.query:
timeseries p95 = percentile(dt.service.request.response_time, 95), filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd p95_ms = arrayAvg(p95) / 1000
| fields p95_ms, p95, interval, timeframe

5.query:
timeseries p99 = percentile(dt.service.request.response_time, 99), filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd p99_ms = arrayAvg(p99) / 1000
| fields p99_ms, p99, interval, timeframe

10.query:
timeseries { p50 = percentile(dt.service.request.response_time, 50), p90 = percentile(dt.service.request.response_time, 90), p95 = percentile(dt.service.request.response_time, 95), p99 = percentile(dt.service.request.response_time, 99) }, filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd p50_ms = p50[] / 1000, p90_ms = p90[] / 1000, p95_ms = p95[] / 1000, p99_ms = p99[] / 1000
| fields timeframe, interval, p50_ms, p90_ms, p95_ms, p99_ms

11.query:
timeseries p95 = percentile(dt.service.request.response_time, 95), by:{endpoint.name}, filter: { k8s.namespace.name == "dydemo" }
| fieldsAdd p95_ms = p95[] / 1000
| fields timeframe, interval, endpoint.name, p95_ms
